export default async function readSyncTasks({ sourceLabel, batchLimit }, context) {
  const tasks = [], seen = new Set();
  const limit = Math.min(batchLimit, 200);
  let cursor;
  do {
    const page = await context.actions.todoist.list_tasks({ label: sourceLabel, limit, ...(cursor ? { cursor } : {}) });
    if (!Array.isArray(page.tasks)) throw new Error('Todoist returned no tasks array');
    tasks.push(...page.tasks.slice(0, batchLimit - tasks.length));
    if (tasks.length >= batchLimit) break;
    cursor = page.nextCursor;
    if (cursor != null && (typeof cursor !== 'string' || !cursor || seen.has(cursor))) throw new Error('Todoist returned an invalid or repeated cursor');
    if (cursor) seen.add(cursor);
  } while (cursor);
  return { tasks, count: tasks.length, sourceLabel };
}

