export default function validateSyncTasks({ tasks }) {
  return { tasks: tasks.map((task) => {
    if (typeof task.id !== 'string' || !task.id || task.id.length > 2000) throw new Error('A Todoist task has an invalid text ID');
    if (typeof task.content !== 'string' || !task.content || task.content.length > 2000) throw new Error('A Todoist task title cannot fit in a Notion title field');
    if (!Array.isArray(task.labels) || task.labels.some((label) => typeof label !== 'string' || !label)) throw new Error('Todoist did not return the task label names');
    if (task.description != null && typeof task.description !== 'string') throw new Error('A Todoist task has an invalid description');
    return { id: task.id, content: task.content, description: task.description ?? '', labels: task.labels };
  }) };
}

