export default function notionTaskRows({ tasks, schema, idProperty }) {
  if (typeof schema.id !== 'string' || !schema.id) throw new Error('Notion returned no data source ID');
  const titles = Object.entries(schema.properties ?? {}).filter(([, property]) => property.type === 'title').map(([name]) => name);
  if (titles.length !== 1) throw new Error('The Notion data source must have exactly one title property');
  if (schema.properties?.[idProperty]?.type !== 'rich_text') throw new Error('Configure a Notion rich-text property for the Todoist ID');
  return { rows: tasks.map((task) => ({ taskId: task.id, parent: { type: 'data_source_id', data_source_id: schema.id }, properties: {
    [titles[0]]: { title: [{ type: 'text', text: { content: task.content } }] },
    [idProperty]: { rich_text: [{ type: 'text', text: { content: task.id } }] },
  } })) };
}

