export default async function createNotionTaskPages({ rows }, context) {
  const created = [];
  for (const { taskId, parent, properties } of rows) {
    const page = await context.actions.notion.create_page({ parent, properties });
    if (typeof page.url !== 'string' || !page.url) throw new Error('The created Notion page has no URL; inspect Notion before retrying');
    const url = new URL(page.url);
    if (!['http:', 'https:'].includes(url.protocol)) throw new Error('The created Notion page has an invalid URL');
    created.push({ taskId, page });
  }
  return { created, count: created.length };
}

