export default function prepareSyncUpdates({ created, tasks, sourceLabel, sentLabel }) {
  if (typeof sentLabel !== 'string' || !sentLabel) throw new Error('Configure a completed-sync label');
  if (created.length !== tasks.length || created.some(({ taskId }, index) => taskId !== tasks[index].id)) throw new Error('Notion page results are not associated with their Todoist tasks');
  const updates = created.map(({ page }, index) => {
    const task = tasks[index];
    return {
    taskId: task.id,
    labels: [...new Set([...task.labels.filter((label) => label !== sourceLabel), sentLabel])],
    description: 'Notion Link:  ' + page.url + '\n\n' + task.description,
    };
  });
  return { updates };
}

